// Один файл: гра «B.L EX:SIM» + /api/ai (Workers AI) + мультиплеєр /api/room (Durable Objects). Вставте в редактор Worker і Deploy.
// Потрібен wrangler.toml з цієї ж папки: прив'язки AI (Workers AI) і ROOMS (Durable Object GameRoom).
/**
 * Cloudflare Pages Function: /api/ai
 * Голос Спостерігача в грі «B.L EX:SIM» через Workers AI (безкоштовний план).
 *
 * GET  /api/ai  -> { ok: true, ai: true|false }  (гра перевіряє, чи є зв'язок і прив'язка AI)
 * POST /api/ai  -> { text }                       (короткі репліки рації, записи щоденника, відповіді гравцю)
 *
 * Потрібна прив'язка Workers AI з іменем AI (див. wrangler.toml або Settings > Bindings у панелі Cloudflare).
 * Необов'язкова змінна середовища AI_MODEL — свій ідентифікатор моделі (наприклад, @cf/google/gemma-3-12b-it).
 */
const MODELS = ['@cf/google/gemma-3-12b-it', '@cf/meta/llama-3.1-8b-instruct-fast', '@cf/meta/llama-3.1-8b-instruct'];
const LANGS = { uk: 'Ukrainian', en: 'English', ru: 'Russian' };
const EVENTS = {
  first: 'first radio contact with the subject',
  morning: 'a new morning has begun',
  night: 'dusk is falling, night is coming',
  storm: 'a thunderstorm is starting',
  wolves: 'wolves are approaching the subject in the dark',
  lowhp: "the subject's health is critical",
  crate: 'you have just lowered a supply crate from the sky on a cable',
  glitch: 'the sky screen visibly glitched a moment ago',
  notes: 'the subject has found the notes of Subject No. 6 (Marta), who vanished',
  final: 'this is the final night of the 7-day experiment',
  blackout: 'the sky screens just glitched and the whole dome lost power; it is pitch dark for about three minutes',
  power: 'the power has just returned after the blackout; somewhere at the end of the dome a service door might now be forced open',
  idle: 'nothing special is happening; make a calm, slightly eerie remark',
  fire: 'the subject has lit a fire',
  sick: 'the subject has an upset stomach from raw water or food'
};

/* простий ліміт на одну адресу в межах ізоляту (основний ліміт — у самій грі) */
const hits = new Map();
function limited(ip) {
  const now = Date.now();
  const arr = (hits.get(ip) || []).filter((t) => now - t < 60000);
  arr.push(now);
  hits.set(ip, arr);
  if (hits.size > 5000) hits.clear();
  return arr.length > 12;
}
const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }
  });
const num = (v, a, b, d) => { v = Number(v); return Number.isFinite(v) ? Math.min(b, Math.max(a, Math.round(v))) : d; };
const str = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f\u007f<>`]/g, ' ').slice(0, n).trim();

function context(c) {
  c = c || {};
  const status = Array.isArray(c.status) ? c.status.slice(0, 6).map((s) => str(s, 20)).join(', ') : '';
  return {
    day: num(c.day, 1, 99, 1), hour: num(c.hour, 0, 23, 12), weather: str(c.weather, 12) || 'clear',
    hp: num(c.hp, 0, 100, 100), food: num(c.food, 0, 100, 50), water: num(c.water, 0, 100, 50), warmth: num(c.warmth, 0, 100, 50),
    status: status || 'none', notes: num(c.notes, 0, 6, 0), fire: !!c.fire, shelter: !!c.shelter, night: !!c.night,
    event: EVENTS[c.event] ? c.event : 'idle',
    question: str(c.question, 200),
    history: Array.isArray(c.history) ? c.history.slice(-6).map((h) => str(h, 200)) : [],
    prole: ['guard', 'technician', 'scientist'].includes(c.prole) ? c.prole : 'scientist', ng: c.ng === 'female' ? 'female' : 'male', pg: c.pg === 'female' ? 'female' : 'male', ev: str(c.ev, 140), mood: str(c.mood, 30), job: str(c.job, 90),
    npc: str(c.npc, 40), nrole: c.nrole === 'guard' ? 'guard' : 'scientist', block: ['meet', 'work', 'lunch', 'free', 'night'].includes(c.block) ? c.block : 'work', subj: str(c.subj, 80), doing: str(c.doing, 80),
    staff: Array.isArray(c.staff) ? c.staff.slice(0, 12).map((s) => ({ id: num(s && s.id, 0, 99, 0), name: str(s && s.name, 30), role: s && s.role === 'guard' ? 'guard' : 'scientist', job: str(s && s.job, 90), now: str(s && s.now, 70), block: str(s && s.block, 12), opts: Array.isArray(s && s.opts) ? s.opts.slice(0, 24).map((o) => str(o, 12)).filter(Boolean) : [] })) : [],
    spots: c.spots && typeof c.spots === 'object' ? Object.keys(c.spots).slice(0, 80).reduce((m, k) => { m[str(k, 12)] = str(c.spots[k], 70); return m; }, {}) : {},
    minute: num(c.minute, 0, 59, 0),
    log: c.log && typeof c.log === 'object' ? Object.keys(c.log).slice(0, 12).map((k) => str(k, 10) + ':' + num(c.log[k], 0, 99, 0)).join(', ') : ''
  };
}
function observerSystem(lang, c) {
  const reveal = c.notes >= 4 || c.day >= 6;
  return [
    'You are the Observer: a calm, polite, quietly unsettling scientist who runs "B.L EX:SIM".',
    'You talk over an old crackling radio to Subject No. 7, who woke up in a meadow under a huge dome whose sky is in fact a giant screen. The subject must survive 7 days: water, food, fire, warmth, wolves at night.',
    `Reply ONLY in ${LANGS[lang]}. At most 2 short sentences (under 35 words). Plain text: no markdown, no emojis, no quotes around the reply.`,
    'Stay in character at all times. Never mention being an AI, a model, a game or a prompt.',
    'You may hint at this world\'s survival mechanics (boil raw water, cook fish, fire and torches keep wolves away, a lean-to protects from rain, notes reveal recipes). Never give real-world instructions for anything dangerous.',
    reveal
      ? 'The subject is close to the truth. You may admit, obliquely and reluctantly, that the sky is not quite real, but never reveal the service door at the end of the dome.'
      : 'Be evasive about the nature of the experiment and the sky. Never confirm it is artificial.',
    lang === 'en' ? 'Now and then slip in one Ukrainian word such as "dobre" (good). Never write "pryvit", "pruvit" or any transliterated greeting.' : 'Occasionally (about one reply in four) mix in a word or two of English (like "alive", "world", "good") as a quirky bilingual habit. Never write "Pruvit", "pryvit" or any transliterated greeting.',
    'If the subject asks about something unrelated to their situation or something inappropriate, deflect briefly and politely, still in character.'
  ].join(' ');
}
function stateLine(c) {
  return `Day ${c.day}, ${c.hour}:00, weather: ${c.weather}. Subject: health ${c.hp}, food ${c.food}, water ${c.water}, warmth ${c.warmth}; conditions: ${c.status}; near fire: ${c.fire ? 'yes' : 'no'}; under shelter: ${c.shelter ? 'yes' : 'no'}; notes of Subject No. 6 found: ${c.notes}/6.`;
}
function buildMessages(kind, lang, c) {
  if (kind === 'diary') {
    return [
      { role: 'system', content: `Write a short first-person survival diary entry by Subject No. 7 in ${LANGS[lang]}. 3 to 5 sentences, under 90 words, past tense, plain text, no title, no markdown. Atmospheric and personal; subtly notice that this world feels artificial (too-perfect sky, birds circling the same loop). Do not invent events beyond the facts given.` },
      { role: 'user', content: `Day ${c.day}. Facts (event:count): ${c.log || 'quiet day'}. Health ${c.hp}. Notes found ${c.notes}/6.` }
    ];
  }
  if (kind === 'npcplan') {
    const spots = Object.keys(c.spots).map((k) => `${k} = ${c.spots[k]}`).join('\n');
    const staff = c.staff.map((s) => `id ${s.id}: ${s.name}, ${s.role}. Job: ${s.job}. Schedule now: ${s.block}. Currently: ${s.now}. Allowed next spots: ${s.opts.join(', ')}`).join('\n');
    return [
      { role: 'system', content: [
        'You direct the everyday life of the staff of a secret research facility. For EACH listed person choose what they do NEXT, like a believable human:',
        'respect their schedule block (staff meeting, lunch, work, free time, night shift), vary activities instead of repeating the current one, give scientists real work at their own stations with occasional short breaks (coffee, window, phone, chatting with a colleague: chat spots come in pairs chatA+chatB or chatC+chatD, assign both halves to two different people), guards stay on post or patrol and rarely take breaks.',
        'Never give the same spot to two people. Use ONLY spot names from that person\'s allowed list.',
        'Answer with ONLY compact JSON, no prose, no markdown: {"plans":[{"id":0,"spot":"lab1","min":25}]} where min is the duration in game minutes (10-90).'
      ].join(' ') },
      { role: 'user', content: `Day ${c.day}, time ${c.hour}:${String(c.minute).padStart(2, '0')}.\nSpots:\n${spots}\nStaff:\n${staff}` }
    ];
  }
  if (kind === 'npcchat') {
    const blocks = { meet: 'a staff meeting', work: 'working hours', lunch: 'the lunch break', free: 'free time after work', night: 'the night shift' };
    const msgs = [{ role: 'system', content: [
      `You are ${c.npc || 'a staff member'}, a ${c.nrole} at the secret research facility "B.L EX:SIM" (test subjects live under a dome whose sky is a giant screen). Your job: ${c.job || c.nrole}. Mood: ${c.mood || 'normal'}.`,
      `You are a ${c.ng === 'female' ? 'woman' : 'man'}: always use the ${c.ng} grammatical gender about yourself (past tense, adjectives). Your coworker is a ${c.pg === 'female' ? 'woman' : 'man'}, address them with the ${c.pg} grammatical gender.`,
      `You are talking face to face with a coworker, a ${c.prole}. Talk like a real, specific person: with opinions, small worries, humour, workplace gossip; react to what they actually said; ask something back sometimes.`,
      `Reply ONLY in ${LANGS[lang]}. One to three short sentences, under 45 words. Plain text, no markdown, no emojis, no quotes, no stage directions. Never mention being an AI, a model or a game.`
    ].join(' ') }, { role: 'user', content: `Context: day ${c.day}, ${c.hour}:00, ${blocks[c.block]}. You are ${c.doing || 'at work'}. Experiment: ${c.subj || 'no data'}. Facility events: ${c.ev || 'nothing unusual'}.` }];
    c.history.forEach((h) => { const me = /^ME:/.test(h); msgs.push({ role: me ? 'assistant' : 'user', content: h.replace(/^(ME|THEM):\s*/, '') }); });
    msgs.push({ role: 'user', content: c.question || '...' });
    return msgs;
  }
  if (kind === 'npc') {
    const blocks = { meet: 'a staff meeting', work: 'working hours', lunch: 'the lunch break', free: 'free time after work', night: 'the night shift' };
    return [
      { role: 'system', content: [
        `You are ${c.npc || 'a staff member'}, a ${c.nrole} working at the secret research facility "B.L EX:SIM", where test subjects live under a dome whose sky is a giant screen.`,
        `You are a ${c.ng === 'female' ? 'woman' : 'man'}: use the ${c.ng} grammatical gender about yourself. A colleague (a ${c.prole}, ${c.pg}) has just stopped you for a quick chat.`, ' Answer as yourself, casually and in character, like a real coworker: tired, ironic or friendly, sometimes gossiping about the experiment, the canteen, the generators or the security checkpoint.',
        `Reply ONLY in ${LANGS[lang]}. One or two short sentences, under 30 words. Plain text, no markdown, no emojis, no quotes. Never mention being an AI, a model or a game.`
      ].join(' ') },
      { role: 'user', content: `It is day ${c.day}, ${c.hour}:00, during ${blocks[c.block]}. Right now you are ${c.doing || 'at work'}. Experiment status: ${c.subj || 'no data'}. Facility events: ${c.ev || 'nothing unusual'}. Say something to your colleague that fits what you are doing.` }
    ];
  }
  if (kind === 'chat') {
    const msgs = [{ role: 'system', content: observerSystem(lang, c) + ' ' + stateLine(c) }];
    if (c.history.length) msgs.push({ role: 'user', content: 'Recent radio log:\n' + c.history.join('\n') });
    msgs.push({ role: 'user', content: 'Subject No. 7 says: ' + (c.question || '...') });
    return msgs;
  }
  return [
    { role: 'system', content: observerSystem(lang, c) },
    { role: 'user', content: stateLine(c) + ` Situation: ${EVENTS[c.event]}. Say one short radio message to the subject.` }
  ];
}
function cleanText(t) {
  if (!t || typeof t !== 'string') return '';
  return t.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/[*#_`]/g, '').replace(/^["«“]|["»”]$/g, '').replace(/\s+/g, ' ').trim().slice(0, 600);
}

/* розбір плану NPC: лише дозволені місця кожної людини, без повторів */
function parsePlans(raw, c) {
  if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
  if (!raw || typeof raw !== 'string') return [];
  raw = raw.replace(/<think>[\s\S]*?<\/think>/g, '');
  let arr = [];
  try { const a = raw.indexOf('{'), b = raw.lastIndexOf('}'); const j = JSON.parse(raw.slice(a, b + 1)); arr = Array.isArray(j) ? j : (j.plans || []); } catch (e) {
    const re = /"id"\s*:\s*(\d+)[^{}]*?"spot"\s*:\s*"([A-Za-z0-9]+)"(?:[^{}]*?"min"\s*:\s*(\d+))?/g; let m;
    while ((m = re.exec(raw))) arr.push({ id: +m[1], spot: m[2], min: m[3] ? +m[3] : 25 });
  }
  const used = new Set(), out = [];
  arr.forEach((p) => { if (!p || typeof p !== 'object') return; const s = c.staff.find((q) => q.id === Number(p.id)); const spot = String(p.spot || '');
    if (!s || !s.opts.includes(spot) || used.has(spot) && !['meeting', 'lunch', 'lounge'].includes(spot)) return; if (out.some((o) => o.id === s.id)) return;
    used.add(spot); out.push({ id: s.id, spot, min: num(p.min, 10, 90, 25) }); });
  return out;
}

async function onRequestGet({ env }) {
  return json({ ok: true, ai: !!(env && env.AI) });
}

async function onRequestPost({ request, env }) {
  if (!env.AI) return json({ error: 'no-ai-binding' }, 503);
  const ip = request.headers.get('cf-connecting-ip') || 'anon';
  if (limited(ip)) return json({ error: 'rate-limited' }, 429);
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: 'bad-json' }, 400); }
  const kind = ['radio', 'diary', 'chat', 'npc', 'npcplan', 'npcchat'].includes(body && body.kind) ? body.kind : 'radio';
  const lang = LANGS[body && body.lang] ? body.lang : 'uk';
  const c = context(body && body.ctx);
  const messages = buildMessages(kind, lang, c);
  const models = env.AI_MODEL ? [env.AI_MODEL].concat(MODELS) : MODELS;
  for (const model of models) {
    try {
      const r = await env.AI.run(model, { messages, max_tokens: kind === 'diary' ? 220 : kind === 'npc' ? 90 : kind === 'npcchat' ? 130 : kind === 'npcplan' ? 600 : 140, temperature: kind === 'npcplan' ? 0.7 : 0.85 });
      const raw = r && (r.response || (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content));
      if (kind === 'npcplan') { const plans = parsePlans(raw, c); if (plans.length) return json({ plans, model }); continue; }
      const text = cleanText(raw);
      if (text) return json({ text, model });
    } catch (e) { /* пробуємо наступну модель */ }
  }
  return json({ error: 'ai-unavailable' }, 502);
}

/**
 * Кімната мультиплеєра B.L EX:SIM (спільна логіка для Durable Object і локального тестового сервера).
 * Протокол — JSON через WebSocket.
 *  клієнт → сервер: name, role, cfg (власник), start (власник), st (стан гравця), ev (подія), score, time (власник), ping
 *  сервер → клієнт: hello, lobby, start, st, ev, left, time, err, pong
 */
const TS = 4 / 3; // ігрових хвилин за реальну секунду (як у грі)
const clean = (s, n) => String(s == null ? '' : s).replace(/[\u0000-\u001f\u007f<>`"\\]/g, '').trim().slice(0, n);
const rid = () => Math.random().toString(36).slice(2, 10);

class RoomCore {
  constructor(now) { this.now = now || (() => Date.now()); this.reset(); }
  reset() { this.cfg = null; this.players = new Map(); this.socks = new Map(); this.owner = null; this.state = 'lobby'; this.seed = 0; this.tot = 480; this.totAt = 0; this.timers = new Map(); this.created = this.now(); }
  info() { return { ok: true, exists: !!this.cfg, state: this.state, n: this.players.size, max: this.cfg ? this.cfg.max : 0 }; }
  curTot() { return this.state === 'play' ? this.tot + (this.now() - this.totAt) / 1000 * TS : this.tot; }
  send(id, obj) { const s = this.socks.get(id); if (s) s.send(JSON.stringify(obj)); }
  bcast(obj, except) { const m = JSON.stringify(obj); for (const [id, s] of this.socks) if (id !== except) s.send(m); }
  list() { return [...this.players.values()].map((p) => ({ id: p.id, name: p.name, role: p.role, score: p.score, on: p.on })); }
  lobby() { this.bcast({ t: 'lobby', owner: this.owner, state: this.state, cfg: this.cfg, players: this.list() }); }
  connect(sock, q) {
    const get = (k) => (q && q.get ? q.get(k) : null);
    const id = clean(get('id'), 16) || rid();
    const name = clean(get('name'), 16) || 'Player';
    if (this.cfg && get('create') === '1' && this.players.size && !this.players.has(id)) { sock.send(JSON.stringify({ t: 'err', e: 'taken' })); sock.close(4009, 'taken'); return; }
    if (!this.cfg) {
      if (get('create') !== '1') { sock.send(JSON.stringify({ t: 'err', e: 'noroom' })); sock.close(4004, 'noroom'); return; }
      this.cfg = { max: Math.max(2, Math.min(10, Number(get('max')) || 4)), mode: 'mixed', taser: get('taser') !== '0', hour: [8, 14, 20].includes(Number(get('hour'))) ? Number(get('hour')) : 8 };
      this.state = 'lobby';
    }
    let p = this.players.get(id);
    if (!p && this.players.size >= this.cfg.max) { sock.send(JSON.stringify({ t: 'err', e: 'full' })); sock.close(4003, 'full'); return; }
    if (!p) { p = { id, name, role: ['sci', 'guard'].includes(get('role')) ? get('role') : 'subj', score: 0, on: true }; this.players.set(id, p); }
    else { p.on = true; if (get('name')) p.name = name; }
    const tm = this.timers.get(id); if (tm) { clearTimeout(tm); this.timers.delete(id); }
    const old = this.socks.get(id); if (old && old !== sock) { try { old.close(4000, 'replaced'); } catch (e) { } }
    this.socks.set(id, sock);
    if (!this.owner || !this.players.has(this.owner)) this.owner = id;
    sock.onMessage((raw) => this.msg(id, raw, sock));
    sock.onClose(() => this.drop(id, sock));
    sock.send(JSON.stringify({ t: 'hello', id, owner: this.owner, state: this.state, cfg: this.cfg }));
    this.lobby();
    if (this.state === 'play') sock.send(JSON.stringify({ t: 'start', seed: this.seed, tot: this.curTot(), cfg: this.cfg, players: this.list() }));
  }
  drop(id, sock) {
    if (this.socks.get(id) !== sock) return;
    this.socks.delete(id);
    const p = this.players.get(id); if (p) p.on = false;
    const grace = this.state === 'play' ? 45000 : 4000;
    this.timers.set(id, setTimeout(() => {
      this.timers.delete(id); if (this.socks.has(id)) return;
      this.players.delete(id); this.bcast({ t: 'left', id });
      if (this.owner === id) { const nx = [...this.players.values()].find((q) => q.on) || [...this.players.values()][0]; this.owner = nx ? nx.id : null; }
      if (!this.players.size) this.reset(); else this.lobby();
    }, grace));
    this.lobby();
  }
  msg(id, raw, sock) {
    if (typeof raw !== 'string' || raw.length > 24000) return;
    let m; try { m = JSON.parse(raw); } catch (e) { return; }
    const p = this.players.get(id); if (!p || !m || typeof m.t !== 'string') return;
    const own = id === this.owner;
    switch (m.t) {
      case 'ping': sock.send('{"t":"pong"}'); break;
      case 'name': p.name = clean(m.name, 16) || p.name; this.lobby(); break;
      case 'role': p.role = ['sci', 'guard', 'tech'].includes(m.role) ? m.role : 'subj'; this.lobby(); break;
      case 'cfg': if (own && this.state === 'lobby' && m.cfg) { this.cfg.max = Math.max(Math.max(2, this.players.size), Math.min(10, Number(m.cfg.max) || this.cfg.max)); this.cfg.mode = 'mixed'; this.cfg.taser = !!m.cfg.taser; if ([8, 14, 20].includes(Number(m.cfg.hour))) this.cfg.hour = Number(m.cfg.hour); this.lobby(); } break;
      case 'start': if (own && this.state === 'lobby') { this.state = 'play'; this.seed = 1 + Math.floor(Math.random() * 1e9); this.tot = (this.cfg.hour || 8) * 60; this.totAt = this.now(); this.bcast({ t: 'start', seed: this.seed, tot: this.tot, cfg: this.cfg, players: this.list() }); this.lobby(); } break;
      case 'lobbyback': if (own && this.state === 'play') { this.state = 'lobby'; this.lobby(); } break;
      case 'time': if (own && this.state === 'play' && Number.isFinite(m.tot)) { this.tot = m.tot; this.totAt = this.now(); this.bcast({ t: 'time', tot: m.tot }, id); } break;
      case 'score': if (Number.isFinite(m.v)) { const v = Math.max(0, Math.min(1e7, Math.round(m.v))); if (v !== p.score) { p.score = v; this.lobby(); } } break;
      case 'st': { const n = this.now(); if (p.stAt && n - p.stAt < 45) return; p.stAt = n; if (m.s && typeof m.s === 'object') this.bcast({ t: 'st', id, s: m.s }, id); break; }
      case 'ev': if (m.e && typeof m.e === 'object') { if (['stun', 'hit', 'para', 'kill'].includes(m.e.k) && !this.cfg.taser) return; if (m.e.to) this.send(clean(m.e.to, 16), { t: 'ev', id, e: m.e }); else this.bcast({ t: 'ev', id, e: m.e }, id); } break;
    }
  }
}

