export class GameRoom {
  constructor(state, env) { this.state = state; this.core = new RoomCore(); }
  async fetch(request) {
    const url = new URL(request.url);
    if ((request.headers.get('Upgrade') || '').toLowerCase() !== 'websocket') return new Response(JSON.stringify(this.core.info()), { headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
    const pair = new WebSocketPair(); const client = pair[0], server = pair[1];
    server.accept();
    const sock = {
      send: (m) => { try { server.send(m); } catch (e) { } },
      close: (c, r) => { try { server.close(c, r); } catch (e) { } },
      onMessage: (fn) => server.addEventListener('message', (e) => fn(typeof e.data === 'string' ? e.data : '')),
      onClose: (fn) => { let done = false; const f = () => { if (!done) { done = true; try { server.close(1000, 'bye'); } catch (e) { } fn(); } }; server.addEventListener('close', f); server.addEventListener('error', f); }
    };
    this.core.connect(sock, url.searchParams);
    return new Response(null, { status: 101, webSocket: client });
  }
}
async function roomRoute(request, env, code) {
  const J = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
  if (!env.ROOMS) return new Response(JSON.stringify({ ok: false, e: 'nodo' }), { status: 501, headers: J });
  if (code === 'PROBE') return new Response(JSON.stringify({ ok: true }), { headers: J });
  return env.ROOMS.get(env.ROOMS.idFromName(code)).fetch(request);
}
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    let p = url.pathname;
    if (p === '/api/ai') {
      if (request.method === 'GET') return onRequestGet({ request, env });
      if (request.method === 'POST') return onRequestPost({ request, env });
      return new Response('Method Not Allowed', { status: 405, headers: { Allow: 'GET, POST' } });
    }
    const rm = p.match(/^\/api\/room\/([A-Z0-9]{4,8})$/);
    if (rm) return roomRoute(request, env, rm[1]);
    if (p === '/') p = '/index.html';
    if (typeof FILES === 'undefined') return env.ASSETS ? env.ASSETS.fetch(request) : new Response('Not found', { status: 404 });
    const f = FILES[p];
    if (!f) return new Response('Not found', { status: 404 });
    const h = { 'Content-Type': f.t, 'X-Content-Type-Options': 'nosniff' };
    h['Cache-Control'] = (p.indexOf('/icons/') === 0) ? 'public, max-age=604800' : 'no-cache';
    return new Response(f.b ? b64(f.d) : f.d, { headers: h });
  }
};

